from itertools import product
from collections import Counter
import json
people=set('KLMNPQR')
west=set('KLQ')
Aopts=['MQR','PQR','KNR','LNP','NPR']
Bopts=['KMQ','KPR','LPR','KNQ','KPQ']
Adays=[{1},{1,7},{3,6},{3},{1,5,7}]
Bdays=[{6,8},{2,7},{3,7,8},{1,2,4},{4}]
As=[a for a in product(*Aopts) if len(set(a))==5]
Bs=[b for b in product(*Bopts) if len(set(b))==5]
hist=Counter()
witness={}
for a in As:
    for b in Bs:
        common=set(a)&set(b)
        if len(common)!=3 or len(common&west)!=1:
            continue
        days={p:set() for p in people}
        for ids, ds in [(a,Adays),(b,Bdays)]:
            for p,d in zip(ids,ds):
                days[p].update(d)
        score=sum(len(d)>=3 for d in days.values())
        hist[score]+=1
        witness.setdefault(score, {'A':''.join(a),'B':''.join(b)})
lo,hi=min(hist),max(hist)
result={'feasible_linkages':sum(hist.values()),'bounds':[lo,hi],'low_witness':witness[lo],'high_witness':witness[hi],'decision':'confirmed' if lo>=5 else 'excluded' if hi<5 else 'undetermined'}
print(json.dumps(result))
print('histogram:',dict(sorted(hist.items())))
# Independently verify endpoint witness scores via day-by-day credited-person sets.
for label,score in [('low_witness',lo),('high_witness',hi)]:
    w=result[label]
    credits=Counter()
    for day in range(1,9):
        present=set()
        for export, ds in [('A',Adays),('B',Bdays)]:
            for p,d in zip(w[export],ds):
                if day in d: present.add(p)
        credits.update(present)
    assert sum(credits[p]>=3 for p in people)==score
    assert len(set(w['A'])&set(w['B'])&west)==1
    print(label,dict(sorted(credits.items())))

